<template>
	<view class="container">
		<u-loading-page :loading="true" v-if="load" fontSize="28rpx" />
		<block v-else>
		<my-tab bgColor="#fff" :datas="tabs" :current="current" @itemClick='itemClick' />
		<scroll-view scroll-y="true" class="scroll" @scrolltolower="loadMore">
			<block v-if="current==0">
			<view class="inner" v-if="lists.length>0">
				<view class="inner-item" v-for="(item,index) in lists" :key="index">
					<view class="left">{{item.goods_price}}</view>
					<view class="center">
						<view class="tit">{{item.goods_name}}</view>
						<view class="day-jifen">每天领取：{{item.day_jifen}}积分</view>
						<view class="day">领取天数：{{item.given_day}}天</view>
					</view>
					<view class="inner-item-bot">
						<button size="mini" class="lq-btn" @click="confirmBuy(item)" :disabled="item.store_count<=0 || item.can_buy==0">{{getBuyText(item)}}</button>
					</view>
				</view>
				<u-loadmore class="load-more" :status="hasMore?'loading':'nomore'" :nomoreText="noMore" />
			</view>
			<view class="empty-container" v-else>
				<u-empty text="暂无相关数据" :icon="emptyIcon" />
			</view>
			</block>
			<block v-else>
				<view class="inner" v-if="order_list.length>0">
					<view class="inner-item" v-for="(item,index) in order_list" :key="index">
						<view class="left">{{item.goods_price}}</view>
						<view class="center">
							<view class="tit">{{item.goods_name}}</view>
							<view class="day-jifen">每天领取：{{item.day_jifen}}积分</view>
							<view class="day">领取天数：{{item.given_day}}天</view>
						</view>
						<view class="inner-item-bot">
							<button size="mini" class="lq-btn" @click="lqJf(item)" :disabled="item.status==2 || item.surplus_day==0">{{getLqText(item)}}</button>
							<view class="day">剩余：{{item.surplus_day}}天</view>
						</view>
					</view>
					<u-loadmore class="load-more" :status="order_hasMore?'loading':'nomore'" :nomoreText="noMore" />
				</view>
				<view class="empty-container" v-else>
					<u-empty text="暂无相关数据" :icon="emptyIcon" />
				</view>
			</block>
		</scroll-view>
		</block>
	</view>
</template>

<script>
	var _this;
	export default {
		data() {
			return {
				tabs: [{
					name: '积分包',
				}, {
					name: '领取积分',
				}],
				current:0,
				jfb_form:{
					pageIndex:1,
					pageSize:20,
				},
				order_form:{
					pageIndex:1,
					pageSize:20,
				},
				order_list:[],
				order_hasMore:false
			}
		},
		onLoad(e) {
			_this = this;
			_this.get_jf_bag_goods()
		},
		methods: {
			getBuyText(item){
				if (item.can_buy==0) {
					return '已购买'
				}else if (item.store_count<=0) {
					return '库存不足'
				}else{
					return '购买'
				}
			},
			getLqText(item){
				if (item.surplus_day==0) {
					return '已领取'
				}else if (item.status==2) {
					return '已领取'
				}else{
					return '领取'
				}
			},
			loadMore(){
				if (_this.current==0) {
					if (_this.hasMore) {
						_this.jfb_form.pageIndex++
						_this.get_jf_bag_goods()
					}
				} else{
					if (_this.order_hasMore) {
						_this.order_form.pageIndex++
						_this.get_jf_bag_order()
					}
				}
			},
			itemClick(current) {
				_this.current = current
				if (current == 0) {
					_this.jfb_form.pageIndex = 1
					_this.lists = []
					_this.get_jf_bag_goods()
				} else{
					_this.order_form.pageIndex = 1
					_this.order_list = []
					_this.get_jf_bag_order()
				}
			},
			async get_jf_bag_goods(){
				const data = await _this.$post('port/request_jf_bag_goods', _this.jfb_form)
				if(data.code==200){
					_this.lists.push(...data.result.list)
					_this.hasMore = data.result.list.length >= _this.jfb_form.pageSize
				}else{
					_this.hasMore = false
				}
				if (_this.load) {
					_this.load = false
				}
			},
			async get_jf_bag_order(){
				const data = await _this.$post('port/jf_bag_dingdan_list', _this.order_form)
				if(data.code==200){
					_this.order_list.push(...data.result.list)
					_this.order_hasMore = data.result.list.length >= _this.order_form.pageSize
				}else{
					_this.order_hasMore = false
				}
			},
			confirmBuy(item){
				let text = `确定购买${item.goods_name}?`
				uni.showModal({
					title:'提示',
					content:text,
					success(res) {
						if(res.confirm){
							_this.buy(item)
						}
					}
				})
			},
			async buy(item){
				let params = {
					goods_id:item.goods_id
				}
				const data = await _this.$post('port/add_jf_bag_order',params)
				if(data.code==200){
					item.store_count--
					item.can_buy = 0
					uni.$u.toast(data.msg)
				}else{
					uni.$u.toast(data.msg)
				}
			},
			async lqJf(item){
				let params = {
					id:item.order_id
				}
				const data = await _this.$post('port/jf_bag_dingdan_lq',params)
				if(data.code==200){
					item.surplus_day--
					item.status = 2
					uni.$u.toast(data.msg)
				}else{
					uni.$u.toast(data.msg)
				}
			}
		}
	}
</script>

